<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\Template\Domain\TemplateRef;
use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersion;

final class TemplateVersionUnitTest extends TestCase
{
    public function test_init_store_values(): void
    {
        // @Arrange
        $one = new TemplateVersion(
            uid: 'one',
            template: new TemplateRef('one'),
            subject: 'one',
            contentHtml: 'one',
            contentText: 'one',
            version: 1,
        );

        // @Act
        $other = $one->toAttributes()->build();
        $calculated = TemplateVersion::calculatedFields();

        // @Assert
        $this->assertEquals([], $calculated);
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getTemplate(), $other->getTemplate());
        $this->assertTrue($one->isTemplateChanged());
        $this->assertEquals($one->getSubject(), $other->getSubject());
        $this->assertTrue($one->isSubjectChanged());
        $this->assertEquals($one->getContentHtml(), $other->getContentHtml());
        $this->assertTrue($one->isContentHtmlChanged());
        $this->assertEquals($one->getContentText(), $other->getContentText());
        $this->assertTrue($one->isContentTextChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
    }
    public function test_replace_change_values(): void
    {
        // @Arrange
        $base = new TemplateVersion(
            uid: 'one',
            template: new TemplateRef('one'),
            subject: 'one',
            contentHtml: 'one',
            contentText: 'one',
            version: 1,
        );
        $other = new TemplateVersion(
            uid: 'other',
            template: new TemplateRef('other'),
            subject: 'other',
            contentHtml: 'other',
            contentText: 'other',
            version: 2,
        );

        // @Act
        $one = $base->replace($other->toAttributes());

        // @Assert
        $this->assertEquals($one->uid(), $base->uid());
        $this->assertEquals($one->getTemplate(), $other->getTemplate());
        $this->assertTrue($one->isTemplateChanged($base));
        $this->assertEquals($one->getSubject(), $other->getSubject());
        $this->assertTrue($one->isSubjectChanged($base));
        $this->assertEquals($one->getContentHtml(), $other->getContentHtml());
        $this->assertTrue($one->isContentHtmlChanged($base));
        $this->assertEquals($one->getContentText(), $other->getContentText());
        $this->assertTrue($one->isContentTextChanged($base));
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged($base));
    }
    public function test_json_compare(): void
    {
        // @Arrange
        $one = new TemplateVersion(
            uid: 'one',
            template: new TemplateRef('one'),
            subject: 'one',
            contentHtml: 'one',
            contentText: 'one',
            version: 1,
        );

        // @Act
        $json = $one->asPublicJson();

        // @Assert
        $this->assertEquals('one', $json['uid']);
        $this->assertEquals('one', $json['template']['$ref']);
        $this->assertEquals('one', $json['subject']);
        $this->assertEquals(1, $json['version']);
    }
    public function test_create_store_values(): void
    {
        // @Arrange
        $one = new TemplateVersion(
            uid: 'one',
            template: new TemplateRef('one'),
            subject: 'one',
            contentHtml: 'one',
            contentText: 'one',
            version: 1,
        );

        // @Act
        $other = TemplateVersion::create($one->toAttributes());

        // @Assert
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getTemplate(), $other->getTemplate());
        $this->assertTrue($one->isTemplateChanged());
        $this->assertEquals($one->getSubject(), $other->getSubject());
        $this->assertTrue($one->isSubjectChanged());
        $this->assertEquals($one->getContentHtml(), $other->getContentHtml());
        $this->assertTrue($one->isContentHtmlChanged());
        $this->assertEquals($one->getContentText(), $other->getContentText());
        $this->assertTrue($one->isContentTextChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
        $this->assertCount(0, $one->getTheEvents());
        $this->assertCount(1, $other->getTheEvents());
    }
    public function test_update_change_values(): void
    {
        $base = new TemplateVersion(
            uid: 'one',
            template: new TemplateRef('one'),
            subject: 'one',
            contentHtml: 'one',
            contentText: 'one',
            version: 1,
        );
        $other = new TemplateVersion(
            uid: 'other',
            template: new TemplateRef('other'),
            subject: 'other',
            contentHtml: 'other',
            contentText: 'other',
            version: 2,
        );

        // @Act
        $one = $base->update($other->toAttributes());

        // @Assert
        $this->assertEquals($one->uid(), $base->uid());
        $this->assertEquals($one->getTemplate(), $other->getTemplate());
        $this->assertTrue($one->isTemplateChanged($base));
        $this->assertEquals($one->getSubject(), $other->getSubject());
        $this->assertTrue($one->isSubjectChanged($base));
        $this->assertEquals($one->getContentHtml(), $other->getContentHtml());
        $this->assertTrue($one->isContentHtmlChanged($base));
        $this->assertEquals($one->getContentText(), $other->getContentText());
        $this->assertTrue($one->isContentTextChanged($base));
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged($base));
        $this->assertCount(0, $other->getTheEvents());
        $this->assertCount(1, $one->getTheEvents());
    }
    public function test_delete_store_values(): void
    {
        // @Arrange
        $one = new TemplateVersion(
            uid: 'one',
            template: new TemplateRef('one'),
            subject: 'one',
            contentHtml: 'one',
            contentText: 'one',
            version: 1,
        );

        // @Act
        $other = $one->delete();

        // @Assert
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getTemplate(), $other->getTemplate());
        $this->assertTrue($one->isTemplateChanged());
        $this->assertEquals($one->getSubject(), $other->getSubject());
        $this->assertTrue($one->isSubjectChanged());
        $this->assertEquals($one->getContentHtml(), $other->getContentHtml());
        $this->assertTrue($one->isContentHtmlChanged());
        $this->assertEquals($one->getContentText(), $other->getContentText());
        $this->assertTrue($one->isContentTextChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
    }
}
